from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    graph = {i: [] for i in range(n)}
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * n
    dist[s] = 0
    queue = deque([(s, 0)])

    while queue:
        u, d = queue.popleft()
        if d > dist[u]:
            continue
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                queue.append((v, dist[v]))

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
