    right = len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return [mid, mid]
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return [-1, -1]
```

