def solve(nums, target):
    def find_first(nums, target):
        low = 0
        high = len(nums) - 1
        first = -1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] == target:
                first = mid
                high = mid - 1
            elif nums[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return first

    def find_last(nums, target):
        low = 0
        high = len(nums) - 1
        last = -1
        while low <= high:
            mid = (low + high) // 2
            if nums[mid] == target:
                last = mid
                low = mid + 1
            elif nums[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return last

    first = find_first(nums, target)
    last = find_last(nums, target)
    return [first, last]
