    left, right = 0, len(nums) - 1
    first_occurrence = -1
    last_occurrence = -1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            first_occurrence = mid
            right = mid - 1  # Continue searching on the left side
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

