        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                last_occurrence = mid
                left = mid + 1  # Continue searching on the right side
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return [first_occurrence, last_occurrence]
    else:
        return [-1, -1]
