        return [-1, -1]

    left = 0
    right = len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            # Found the target, now find the first and last occurrences
            first = mid
            while first > 0 and nums[first - 1] == target:
                first -= 1

            last = mid
            while last < len(nums) - 1 and nums[last + 1] == target:
                last += 1

            return [first, last]
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return [-1, -1]
```

